(()=>{"use strict";
let rows=[],adminRows=[],sheetRows=[],loading=false,lastSheetFetch=0;const selectedFilters=new Set(["brasil"]);
const norm=v=>String(v??"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"_").replace(/^_+|_+$/g,"");
const bool=v=>["true","1","sim","yes","ativo","on","verdadeiro"].includes(String(v??"").trim().toLowerCase());
const num=v=>{const n=parseFloat(String(v??"").trim().replace(",","."));return Number.isFinite(n)?n:0};
const inferRegion=title=>/\b(latam|sea|usa|mea|india|bangladesh|pakistan|nepal|global|world|ewc|mundial)\b/i.test(String(title||""))?"internacional":"brasil";
const normalizeLevel=value=>String(value||"").trim().toLowerCase()==="amador"?"amador":"oficial";
function parseDateBR(value){const v=String(value??"").trim();if(!v)return null;let m=v.match(/^(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{1,2}):(\d{2})(?::(\d{2}))?$/);if(m){const[,y,mo,d,h,mi,se="00"]=m,x=new Date(`${y}-${String(mo).padStart(2,"0")}-${String(d).padStart(2,"0")}T${String(h).padStart(2,"0")}:${mi}:${se}-03:00`);return Number.isNaN(x.getTime())?null:x}m=v.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})[ T](\d{1,2}):(\d{2})(?::(\d{2}))?$/);if(m){const[,d,mo,y,h,mi,se="00"]=m,x=new Date(`${y}-${String(mo).padStart(2,"0")}-${String(d).padStart(2,"0")}T${String(h).padStart(2,"0")}:${mi}:${se}-03:00`);return Number.isNaN(x.getTime())?null:x}const x=new Date(v);return Number.isNaN(x.getTime())?null:x}
function parseTSV(text){const out=[];let row=[],cell="",quoted=false;const s=String(text??"").replace(/^\uFEFF/,"");for(let i=0;i<s.length;i++){const c=s[i],n=s[i+1];if(c==='"'){if(quoted&&n==='"'){cell+='"';i++}else quoted=!quoted}else if(c==='\t'&&!quoted){row.push(cell);cell=""}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&n==='\n')i++;row.push(cell);cell="";if(row.some(v=>String(v).trim()))out.push(row);row=[]}else cell+=c}row.push(cell);if(row.some(v=>String(v).trim()))out.push(row);return out}
function parseSheet(text){const table=parseTSV(text);if(table.length<2)return[];const head=table[0].map(norm),idx=aliases=>head.findIndex(h=>aliases.map(norm).includes(h));const map={titulo:idx(["torneio","titulo","evento","live"]),faseDia:idx(["fase_dia","fase_e_dia","fase","rodada"]),canal:idx(["canal","streamer","criador"]),url:idx(["url","link","live_url"]),categoria:idx(["categoria","tipo"]),regiao:idx(["regiao","região","region"]),nivel:idx(["nivel","nível","escopo","categoria_transmissao"]),ativo:idx(["ativo","ao_vivo","aovivo","live"]),data_hora:idx(["data_hora","datahora","data_e_hora","inicio","data"]),duracao:idx(["duracao","duracao_horas","horas"]),linkMode:idx(["link_mode","modo_link","liberar_link","disponibilidade_link"])};return table.slice(1).map((r,i)=>{const get=(k,fallback)=>map[k]>=0?r[map[k]]:r[fallback],titulo=String(get("titulo",0)??"").trim(),categoria=String(get("categoria",3)??"").trim().toLowerCase(),rawRegion=String(map.regiao>=0?get("regiao",-1):"").trim().toLowerCase(),rawLevel=String(map.nivel>=0?get("nivel",-1):"").trim().toLowerCase();return{id:`sheet-live-${i}`,titulo,faseDia:String(map.faseDia>=0?get("faseDia",-1):"").trim(),canal:String(get("canal",1)??"").trim(),url:String(get("url",2)??"").trim(),regiao:["brasil","internacional"].includes(rawRegion)?rawRegion:inferRegion(titulo),nivel:normalizeLevel(rawLevel||(["amador","oficial"].includes(categoria)?categoria:"oficial")),ativo:bool(get("ativo",4)),data_hora:String(get("data_hora",5)??"").trim(),duracaoMinutos:Math.max(0,Math.round(num(get("duracao",6))*60)),linkMode:String(map.linkMode>=0?get("linkMode",-1):"always").trim().toLowerCase()==="schedule"?"schedule":"always",source:"sheet"}}).filter(r=>r.titulo.length>2)}
function parseAdmin(data){return Object.entries(data||{}).map(([id,raw])=>{const mins=raw?.duracaoMinutos!=null?Number(raw.duracaoMinutos):num(raw?.duracao)*60,links=(Array.isArray(raw?.links)?raw.links:Object.values(raw?.links||{})).map((x,i)=>({label:String(x?.label||x?.nome||x?.canal||`Alternativa ${i+1}`).trim(),url:String(x?.url||x?.link||"").trim()})).filter(x=>x.url),titulo=String(raw?.torneio||raw?.titulo||"").trim(),rawRegion=String(raw?.regiao||"").trim().toLowerCase(),legacyCategory=String(raw?.categoria||"").trim().toLowerCase();return{id:String(raw?.id||id),titulo,faseDia:String(raw?.faseDia||raw?.fase_dia||"").trim(),canal:String(raw?.canal||"").trim(),url:String(raw?.url||"").trim(),embedEnabled:Boolean(raw?.embedEnabled),embedUrl:String(raw?.embedUrl||"").trim(),embedVideoId:String(raw?.embedVideoId||"").trim(),links,regiao:["brasil","internacional"].includes(rawRegion)?rawRegion:inferRegion(titulo),nivel:normalizeLevel(raw?.nivel||raw?.escopo||(["amador","oficial"].includes(legacyCategory)?legacyCategory:"oficial")),ativo:false,data_hora:String(raw?.inicio||raw?.data_hora||"").trim(),duracaoMinutos:Number.isFinite(mins)?Math.max(0,Math.round(mins)):0,linkMode:String(raw?.linkMode||"always").trim().toLowerCase()==="schedule"?"schedule":"always",source:"admin"}}).filter(r=>r.titulo.length>2&&r.data_hora)}
function liveKey(r){const d=parseDateBR(r.data_hora);return `${norm(r.titulo)}|${d?d.getTime():String(r.data_hora)}`}
function mergeRows(){const merged=new Map;sheetRows.forEach(r=>merged.set(liveKey(r),r));adminRows.forEach(r=>merged.set(liveKey(r),r));rows=Array.from(merged.values())}
function durationMinutes(r){return Math.max(0,Number(r.duracaoMinutos||0))}
function statusFor(r,now){const start=parseDateBR(r.data_hora),mins=durationMinutes(r),end=start&&mins>0?new Date(start.getTime()+mins*60000):null,inWindow=!!(start&&end&&now>=start&&now<=end),future=!!(start&&now<start);return{start,end,inWindow,future,isLive:!!(r.ativo||inWindow)}}
const UPCOMING_PAGE_SIZE=3;let upcomingVisible=3;
function passesFilters(r){const region=["brasil","internacional"].filter(x=>selectedFilters.has(x)),level=["amador","oficial"].filter(x=>selectedFilters.has(x));return(!region.length||region.includes(r.regiao))&&(!level.length||level.includes(r.nivel))}
function syncFilterButtons(){document.querySelectorAll("[data-live-filter]").forEach(btn=>{const key=btn.dataset.liveFilter,active=key==="todos"?selectedFilters.size===0:selectedFilters.has(key);btn.classList.toggle("is-active",active);btn.setAttribute("aria-pressed",active?"true":"false")})}
function resolveLiveUrl(value){const raw=String(value||"").trim();if(!raw)return"";try{const u=new URL(raw,location.href),host=u.hostname.toLowerCase().replace(/^www\./,"");if(host==="youtube.com"||host==="m.youtube.com"){let path=u.pathname.replace(/\/+$/,"");if(/^\/(?:@[^/]+|channel\/[^/]+|c\/[^/]+|user\/[^/]+)$/i.test(path)){u.pathname=path+"/live";u.search="";u.hash="";return u.toString()}if(/^\/(?:@[^/]+|channel\/[^/]+|c\/[^/]+|user\/[^/]+)\/streams$/i.test(path)){u.pathname=path.replace(/\/streams$/i,"/live");u.search="";u.hash="";return u.toString()}}return u.toString()}catch(e){return raw}}
function youtubeVideoId(value){const raw=String(value||"").trim();if(!raw)return"";try{const u=new URL(raw,location.href),host=u.hostname.toLowerCase().replace(/^www\./,"");let id="";if(host==="youtu.be")id=u.pathname.split("/").filter(Boolean)[0]||"";else if(["youtube.com","m.youtube.com","music.youtube.com","youtube-nocookie.com"].includes(host)){id=u.searchParams.get("v")||"";if(!id){const m=u.pathname.match(/^\/(?:live|embed|shorts)\/([^/?#]+)/i);if(m)id=m[1]}}return/^[A-Za-z0-9_-]{6,20}$/.test(id)?id:""}catch(e){return""}}
let activeLiveEmbedOpener=null;
function closeLiveEmbedModal(){
 const modal=document.querySelector(".cff-live-modal");
 if(modal)modal.remove();
 if(activeLiveEmbedOpener){
  activeLiveEmbedOpener.setAttribute("aria-expanded","false");
  activeLiveEmbedOpener=null;
 }
}
function openLiveEmbedModal(r,videoId,opener){
 closeLiveEmbedModal();
 activeLiveEmbedOpener=opener||null;
 if(activeLiveEmbedOpener)activeLiveEmbedOpener.setAttribute("aria-expanded","true");
 const modal=document.createElement("div");
 modal.className="cff-live-modal";
 modal.setAttribute("role","dialog");
 modal.setAttribute("aria-modal","true");
 modal.setAttribute("aria-label",`Assistir ${r.titulo}`);
 modal.innerHTML=`<div class="cff-live-modal-dialog"><div class="cff-live-modal-head"><div><small>AO VIVO</small><strong></strong><span></span></div><button class="cff-live-modal-close" type="button" aria-label="Fechar transmissão">✕</button></div><div class="cff-live-modal-player"></div></div>`;
 modal.querySelector(".cff-live-modal-head strong").textContent=r.titulo;
 modal.querySelector(".cff-live-modal-head span").textContent=[r.faseDia,r.canal].filter(Boolean).join(" • ");
 const iframe=document.createElement("iframe");
 iframe.src=`https://www.youtube.com/embed/${encodeURIComponent(videoId)}?autoplay=1&playsinline=1&rel=0`;
 iframe.title=`Transmissão ao vivo - ${r.titulo}`;
 iframe.referrerPolicy="strict-origin-when-cross-origin";
 iframe.allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share";
 iframe.allowFullscreen=true;
 modal.querySelector(".cff-live-modal-player").appendChild(iframe);
 modal.querySelector(".cff-live-modal-close").addEventListener("click",closeLiveEmbedModal);
 modal.addEventListener("click",event=>{if(event.target===modal)closeLiveEmbedModal()});
 document.body.appendChild(modal);
 modal.querySelector(".cff-live-modal-close")?.focus({preventScroll:true});
}

function liveLinkAvailable(r,s,now,url=r.url){if(!url)return false;return r.linkMode!=="schedule"||!!(s.start&&now>=s.start)}
function liveLinks(r){const out=[];if(r.url)out.push({label:r.canal||"Principal",url:r.url});(r.links||[]).forEach((x,i)=>{if(x?.url&&!out.some(y=>y.url===x.url))out.push({label:x.label||`Alternativa ${i+1}`,url:x.url})});return out}
function buildLiveCard(r,s,now){
 const el=document.createElement("div");
 el.className="live-card "+(s.isLive?"ativo":"agendado");
 let badge="";
 if(s.isLive){badge="AO VIVO"}else{
  const ms=Math.max(0,s.start-now),totalMins=Math.ceil(ms/6e4),days=Math.floor(totalMins/1440),hours=Math.floor(totalMins%1440/60),mins=totalMins%60;
  if(totalMins<=15){badge="COMEÇA JÁ";el.classList.add("is-starting-soon")}
  else{const parts=[];if(days>0)parts.push(`${days}d`);if(hours>0||days>0)parts.push(`${hours}h`);parts.push(`${mins}min`);badge=parts.join("")}
 }
 el.innerHTML=`<div class="live-dot"></div><div class="live-card-info"><div class="live-card-titulo"></div><div class="live-card-canal"></div></div><span class="live-card-badge"></span>`;
 el.querySelector(".live-card-titulo").textContent=r.titulo;
 el.querySelector(".live-card-canal").textContent=[r.faseDia,r.canal].filter(Boolean).join(" • ");
 el.querySelector(".live-card-badge").textContent=badge;

 const actions=document.createElement("div");
 actions.className="cff-live-link-stack";

 const videoId=r.embedVideoId||youtubeVideoId(r.embedUrl||r.url);
 if(s.isLive&&r.embedEnabled&&videoId){
  const embedButton=document.createElement("button");
  embedButton.className="cff-live-action cff-live-embed-toggle";
  embedButton.type="button";
  embedButton.textContent="▶ ASSISTIR AQUI";
  embedButton.setAttribute("aria-expanded","false");
  embedButton.addEventListener("click",()=>openLiveEmbedModal(r,videoId,embedButton));
  actions.appendChild(embedButton);
 }

 if(liveLinkAvailable(r,s,now,r.url)){
  const official=document.createElement("a");
  official.className="cff-live-action cff-live-action-official";
  official.href=resolveLiveUrl(r.url);
  official.target="_blank";
  official.rel="noopener noreferrer";
  official.setAttribute("aria-label",`Abrir transmissão oficial de ${r.titulo}`);
  const title=document.createElement("span");
  title.className="cff-live-action-title";
  title.textContent="TRANSMISSÃO OFICIAL";
  official.appendChild(title);
  actions.appendChild(official);
 }

 (r.links||[]).forEach((x,i)=>{
  if(!x?.url||!liveLinkAvailable(r,s,now,x.url))return;
  const alt=document.createElement("a");
  alt.className="cff-live-action cff-live-action-alt";
  alt.href=resolveLiveUrl(x.url);
  alt.target="_blank";
  alt.rel="noopener noreferrer";
  alt.setAttribute("aria-label",`Abrir transmissão alternativa ${x.label||i+1}`);
  const title=document.createElement("span");
  title.className="cff-live-action-title";
  title.textContent="TRANSMISSÃO ALT.";
  const channel=document.createElement("small");
  channel.textContent=x.label||`Alternativa ${i+1}`;
  alt.append(title,channel);
  actions.appendChild(alt);
 });

 if(actions.childElementCount)el.appendChild(actions);
 return el
}
function render(){const on=document.getElementById("lives-on-container"),up=document.getElementById("lives-upcoming-container");if(!on||!up)return;on.replaceChildren();up.replaceChildren();syncFilterButtons();const now=new Date(),visible=rows.filter(passesFilters).map(r=>({r,s:statusFor(r,now)})).filter(x=>x.s.isLive||x.s.future).sort((a,b)=>{if(a.s.isLive!==b.s.isLive)return a.s.isLive?-1:1;return(a.s.start?.getTime()||0)-(b.s.start?.getTime()||0)}),liveItems=visible.filter(x=>x.s.isLive),upcomingItems=visible.filter(x=>!x.s.isLive);liveItems.forEach(({r,s})=>on.appendChild(buildLiveCard(r,s,now)));upcomingItems.slice(0,upcomingVisible).forEach(({r,s})=>up.appendChild(buildLiveCard(r,s,now)));const onEmpty=document.getElementById("lives-on-empty"),upEmpty=document.getElementById("lives-up-empty"),more=document.getElementById("lives-upcoming-more");if(onEmpty){onEmpty.style.display=liveItems.length?"none":"block";onEmpty.textContent="Nenhuma live no ar com esses filtros."}if(upEmpty)upEmpty.style.display=upcomingItems.length?"none":"block";if(more){more.hidden=upcomingItems.length<=upcomingVisible;more.textContent=`Ver próximas (${Math.min(UPCOMING_PAGE_SIZE,Math.max(0,upcomingItems.length-upcomingVisible))}) →`}}
async function fetchText(url,timeout=7000){const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),timeout);try{const res=await fetch(url,{cache:"default",signal:ctl.signal});if(!res.ok)throw new Error(`HTTP ${res.status}`);return await res.text()}finally{clearTimeout(timer)}}
async function fetchJSON(url,timeout=7000){const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),timeout);try{const res=await fetch(url,{cache:"default",signal:ctl.signal});if(!res.ok)throw new Error(`HTTP ${res.status}`);return await res.json()}finally{clearTimeout(timer)}}
async function loadAdmin(){const base=String(window.CFF_CONFIG?.firebase?.databaseURL||"").replace(/\/$/,"");if(!base){adminRows=[];return}try{adminRows=parseAdmin(await fetchJSON(`${base}/adminLives.json`))}catch(e){adminRows=[]}}
async function loadSheet(force=false){const base=window.CFF_CONFIG?.sheets?.lives;if(!base)return;const now=Date.now();if(!force&&sheetRows.length&&now-lastSheetFetch<300000)return;try{const text=await fetchText(base);sheetRows=parseSheet(text);lastSheetFetch=now}catch(e){if(!sheetRows.length)sheetRows=[]}}
async function load(opts={}){if(loading)return;loading=true;try{await Promise.all([loadAdmin(),loadSheet(!!opts.forceSheet)]);mergeRows();render()}catch(e){if(!opts.silent&&!rows.length)render()}finally{loading=false}}
window.loadLives=load;window.updateLivesTick=render;window.buildLivesHTML=render;
document.addEventListener("click",e=>{const alt=e.target.closest?.("[data-live-url]");if(alt){e.preventDefault();e.stopPropagation();window.open(alt.dataset.liveUrl,"_blank","noopener,noreferrer");return}const filter=e.target.closest?.("[data-live-filter]");if(filter){const key=filter.dataset.liveFilter;if(key==="todos")selectedFilters.clear();else if(selectedFilters.has(key))selectedFilters.delete(key);else selectedFilters.add(key);upcomingVisible=UPCOMING_PAGE_SIZE;render();return}const more=e.target.closest?.("#lives-upcoming-more");if(more){upcomingVisible+=UPCOMING_PAGE_SIZE;render()}});
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&document.querySelector(".cff-live-modal")){closeLiveEmbedModal();return}const alt=e.target.closest?.("[data-live-url]");if(alt&&(e.key==="Enter"||e.key===" ")){e.preventDefault();e.stopPropagation();window.open(alt.dataset.liveUrl,"_blank","noopener,noreferrer")}});

function boot(){load();if(window.livesInterval)clearInterval(window.livesInterval);if(window.livesRefreshInterval)clearInterval(window.livesRefreshInterval);window.livesInterval=setInterval(render,30000);window.livesRefreshInterval=setInterval(()=>load({silent:true}),60000)}
document.readyState==="loading"?document.addEventListener("DOMContentLoaded",boot,{once:true}):boot();
})();
